import{_ as o,o as t,c as n,a2 as e}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"XCOM 2 — 게임 로직 백과사전","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-XCOM-2.md","filePath":"rules/Ref-XCOM-2.md"}'),l={name:"rules/Ref-XCOM-2.md"};function s(a,r,i,g,S,h){return t(),n("div",null,[...r[0]||(r[0]=[e('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 이 문서의 S1–S19 대응표는 회수하지 못했으므로 해당 인용으로 외부 검증 완료를 주장하지 않는다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>xcom-2.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="xcom-2-—-게임-로직-백과사전" tabindex="-1">XCOM 2 — 게임 로직 백과사전 <a class="header-anchor" href="#xcom-2-—-게임-로직-백과사전" aria-label="Permalink to &quot;XCOM 2 — 게임 로직 백과사전&quot;">​</a></h1><blockquote><p>출처: [S1]~[S19] xcom.fandom.com (api.php wikitext), Steam 스토어. 태그: [문서]/[추론]/[미확인].</p></blockquote><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><ul><li><strong>장르</strong>: 턴제 전술 + 전략 경영 (2레이어 하이브리드). 개발 Firaxis Games, 2016년 2월 출시. 확장 <strong>War of the Chosen(WotC, 2017)</strong> [S19][문서]</li><li><strong>핵심 특징</strong>: 전작의 패배 이후가 배경. 외성인 ADVENT 정권이 지배하는 지구에서, 플레이어(사령관)는 납치된 이동식 기지 <strong>Avenger</strong>에서 게릴라 저항 조직 XCOM을 지휘한다 [S15][문서]</li><li><strong>설계상 특징</strong>: ① 전략 레이어의 <strong>파멸 타이머(Avatar Project)</strong>, ② 전술 레이어의 <strong>턴제한 목표</strong>, ③ 영구 사망(ironman성 로그라이크 긴장), ④ <strong>은신(Concealment)으로 시작하는 전투</strong> — 전작과의 가장 큰 차별점 [S1][S4][S7][문서]</li><li>문서는 본편 기준으로 서술하고 WotC 전용 요소(Chosen, 결속, 피로, 비밀 작전, 저항 세력)는 별도 표기.</li></ul><h2 id="_2-코어-루프" tabindex="-1">2. 코어 루프 <a class="header-anchor" href="#_2-코어-루프" aria-label="Permalink to &quot;2. 코어 루프&quot;">​</a></h2><p>반복 사이클 [S2][S4][문서]:</p><ol><li><strong>Geoscape에서 시간 진행</strong>: Avenger를 스캔 지점에 두고 스캔 → 게임 내 일수 경과 [S2][문서]</li><li><strong>미션 등장</strong>: 게릴라 옵스(월 최대 3개 제시, 1개만 선택 수행), 스토리 미션, 보급 습격, UFO 등이 캘린더에 팝업 [S3][S4][문서]</li><li><strong>전술 미션 수행</strong>: 4~6인 분대로 은신 상태 시작, 턴제한 내 목표 달성 [S4][S7][문서]</li><li><strong>Avenger 내 경영</strong>: 전쟁 획득 자원(공급품/정보/합금/엘레리움)으로 시설 건설, 연구, 장비 제작 [S14][S15][S17][문서]</li><li><strong>월간 정산</strong>: 보급품 air drop 수령, Dark Event 갱신, 숙련도/부상 관리 [S3][S17][문서]</li></ol><ul><li>루프의 구동력은 <strong>양방향 시간 압박</strong>: 전략 레이어의 Avatar 게이지와 전술 레이어의 턴 타이머가 서로를 강제한다(§10) [추론 — S1, S4의 시스템 조합으로부터].</li></ul><h2 id="_3-진행-구조" tabindex="-1">3. 진행 구조 <a class="header-anchor" href="#_3-진행-구조" aria-label="Permalink to &quot;3. 진행 구조&quot;">​</a></h2><ul><li><strong>도입</strong>: Commander 구출 → 동력핵 회수로 Avenger 비행 가능 → 첫 지역에서 연락망 확장 [S15][문서]</li><li><strong>중반</strong>: 연구 트리(무기/장갑 티어: 관성→자기→플라즈마)로 병력 강화, 외성인 시설(Alien Facility) 파괴로 Avatar 진척 감소 [S1][S14][문서]. 시설은 최대 5개 동시 존재, 등장 시 진척 +1(사령관 난이도 25% 확률 +2) [S1][문서]</li><li><strong>후반</strong>: 블랙사이트 → Forge → Psi Gate 등 스토리 미션이 진척 1~3씩 감소시킴 [S1][문서]. 최종 Alien Fortress Assault로 종결.</li><li><strong>게임 오버 조건</strong>: Avatar 게이지 12칸 완료 → 카운트다운(난이도별 15~27일) 내 감소 실패 시 패배. 12칸 미만으로 내려도 카운트다운은 일시정지일 뿐 리셋 안 됨(7일 미만이었을 때만 7일로 리셋) [S1][문서]. WotC에서는 Chosen의 지식 만달성 시 Avenger 공격 패배 추가 [S5][문서]</li></ul><h2 id="_4-경제-시스템" tabindex="-1">4. 경제 시스템 <a class="header-anchor" href="#_4-경제-시스템" aria-label="Permalink to &quot;4. 경제 시스템&quot;">​</a></h2><ul><li><strong>공급품(Supplies)</strong>: 범용 화폐. 시설 건설/유지비, 장비 제작, 병사 모집, 무전 중계기 건설에 사용. 월간 보급 air drop(연락 지역 수·중계기 수에 비례) + 임무 보상 + 흑시장 판매로 획득. 시작 시 175 [S16][S17][문서]</li><li><strong>정보(Intel)</strong>: 지역 연락, 흑시장 구매, 은닉 Dark Event 확인(20~30)에 사용 [S2][S3][S16][문서]</li><li><strong>합금/엘레리움 코어·결정</strong>: 무기·중장갑 제작 재료, 전투/습격에서 획득 [S16][문서]</li><li><strong>인력</strong>: 과학자(연구 가속), 엔지니어(건설·제작 가속, 시설 배치 보너스). 흑시장·미션·비밀 작전으로 확보 [S16][S6][문서]</li><li><strong>흑시장</strong>: 2개월차 개설. 월마다 재고 교체, 특정 아이템에 &#39;관심&#39; 프리미엄 지불. 정보로 구매/공급품으로 판매 [S16][문서]</li><li>Dark Event가 경제를 직접 타격함(모집 비용 상승, 보급 감소, 정보 비용 상승, 흑시장 폐업 6주) — 경제는 적의 공격 대상이기도 함 [S3][문서]</li></ul><h2 id="_5-캐릭터-병사-시스템" tabindex="-1">5. 캐릭터/병사 시스템 <a class="header-anchor" href="#_5-캐릭터-병사-시스템" aria-label="Permalink to &quot;5. 캐릭터/병사 시스템&quot;">​</a></h2><ul><li><strong>모집</strong>: 신병(Rookie)은 Armory에서 공급품으로 고용, 승진 시(Squaddie) 무작위 병과 배정 [S12][문서]</li><li><strong>병과(본편 4+1)</strong>: Ranger(산탄총/검), Grenadier(체인건/유탄발사기), Specialist(그렘린 드론 원격 지원/해킹), Sharpshooter(저격총/권총), Psi Operative(Psi Lab 훈련으로 전직). DLC로 SPARK(로봇) 추가 [S12][문서]</li><li><strong>계급·경험치</strong>: 킬 수 기반 승진(최대 Colonel). 난이도별 필요 킬 상이(Legend Colonel 175킬). 미션당 승진 1회 제한. 킬 어시스트(클래스별 3~5어시스트=1킬) [S12][문서]</li><li><strong>능력</strong>: 계급당 스킬 트리 2选1. AWC(Advanced Warfare Center) 건설 시 타 병과 능력 &#39;숨은 능력&#39; 획득 가능 [S12][문서]</li><li><strong>커스터마이징</strong>: 이름/국적/외모/장비 색상/성격(태도) 전면 커스텀. 일부는 계급(중사~) 잠금 해제 [S12][문서]</li><li><strong>부상·사망</strong>: 부상병 배치 불가(회복에 게임 시간 소요). 영구 사망 존재. 정예병의 상실이 실질 난이도 상승으로 이어짐 [S12][추론]</li><li><strong>PCS(Personal Combat Sim)</strong>: 신경 이식칩. Aim/회피/HP/의지/기동성 영구 강화, 3티어. 1인 1칩, 교체 시 기존칩 소실 [S18][문서]</li><li><strong>WotC 추가</strong>: <ul><li><strong>영웅 병과</strong>(Reaper/Skirmisher/Templar): 저항 세력 전용, 계급 대신 **어빌리티 포인트(AP)**로 스킬 구매. Combat Intelligence 등급이 승진당 AP 배수 결정 [S12][문서]</li><li><strong>결속(Bond)</strong>: 동행 임무로 결속도 상승 → Lv1 Teamwork(행동 부여), Lv2 Spotter/Stand By Me, Lv3 Dual Strike(동시 사격) [S13][문서]</li><li><strong>피로(Tired/Shaken)</strong>: 의지 소모로 누적. 피로병 재배치 시 부정적 성향 획득 위험 — 병력 로테이션 강제 [S12][문서]</li></ul></li></ul><h2 id="_6-전투-시스템" tabindex="-1">6. 전투 시스템 <a class="header-anchor" href="#_6-전투-시스템" aria-label="Permalink to &quot;6. 전투 시스템&quot;">​</a></h2><ul><li><strong>턴 구조</strong>: 1행동=이동 or 사격, 병사는 행동점 2개. 임무는 대부분 <strong>턴 제한(기본 6~8턴)</strong> 목표 수행형 [S4][문서]</li><li><strong>엄폐</strong>: 낮은 엄폐 방어+20, 높은 엄폐 +40. Hunker Down 시 추가 +30 방어·회피+50 [S8][문서]</li><li><strong>측면 공격(Flanking)</strong>: 엄폐 밖에서 조준 시 치명타 확률 보너스(XCOM +40%, 적은 난이도별 +33~40%) [S9][문서]</li><li><strong>은신(Concealment)</strong>: 대부분 미션 은신 시작. 적 감지 반경 진입·발포·유리 파괴로 해제. 해제 후 재은신 불가(예외: Ranger Conceal, Reaper Shadow). 은신 중 경계 사격은 명중 패널티 면제 — <strong>매복(ambush) 세팅</strong>이 핵심 전술 [S7][문서]</li><li><strong>경계(Overwatch)</strong>: 이동 적에 반응 사격. 명중률 ×0.7(질주 적 ×0.6) 패널티 [S10][문서]</li><li><strong>포드(Pod) 시스템</strong>: 적은 리더+추종자 그룹(포드)으로 순찰. 미션 난이도별 2~10 포드. 한 번에 한 포드만 활성화 — <strong>포드 격리·한 포드씩 처리</strong>가 기본 전략 [S11][문서]</li><li><strong>파괴 가능 지형</strong>: 엄폐물 폭발/돌진 파괴. 건물 붕괴로 엄폐·고지 무효화가 전술적 무기 [S8][문서]</li><li>해킹(터렛/워크스테이션), 클레이모어, 그랩 후크 등 환경 인터랙션 다수 [S4][S7][문서]</li></ul><h2 id="_7-지도-세계-구조" tabindex="-1">7. 지도/세계 구조 <a class="header-anchor" href="#_7-지도-세계-구조" aria-label="Permalink to &quot;7. 지도/세계 구조&quot;">​</a></h2><ul><li><strong>Geoscape</strong>: Avenger 함교에서 접근하는 지구 전략 지도. 16개 지역/6대륙, 각 지역은 2~4개 인접 지역 연결. 시작 지역 무작위 [S2][문서]</li><li><strong>연락망</strong>: Resistance Communications 연구 후 정보(Intel) 소모해 인접 지역 연락. Resistance Comms 시설로 연락 한도 확장. 연락 지역마다 월 보급 증가 [S2][문서]</li><li><strong>무전 중계기(Radio Relay)</strong>: 지역에 건설 → 인접 지역 연락 비용 감소 + 보급 증가. 대륙 전 지역 중계기 시 <strong>대륙 보너스</strong> 획득(무작위) [S2][문서]</li><li><strong>시간 흐름</strong>: 스캔으로 일수 진행. Avenger 이동·스캔 중 이벤트(루머)·미션 타이머 병행 [S2][문서]</li><li>WotC: 지역별로 <strong>Chosen이 지배권</strong> — 어느 지역에서 작전하느냐가 만나는 적 결정 [S5][문서]</li></ul><h2 id="_8-외교-세력" tabindex="-1">8. 외교/세력 <a class="header-anchor" href="#_8-외교-세력" aria-label="Permalink to &quot;8. 외교/세력&quot;">​</a></h2><ul><li>본편의 &#39;외교&#39;는 <strong>저항 연락망 확장</strong> 형태 — 국가 간 외교가 아니라 점령 지구의 민심·조직망 확보 [S2][추론]</li><li><strong>ADVENT</strong>: 지배 세력. Dark Event로 주기적 저항 탄압 [S3][문서]</li><li><strong>WotC 저항 3세력</strong>(Reapers·Skirmishers·Templars): 각각 Chosen 하나의 라이벌. <strong>영향력(Influence)</strong> 단계 상승 시 저항 명령 슬롯 확보(세력당 최대 2) [S5][S6][문서]</li><li><strong>Chosen 라이벌 시스템(WotC)</strong>: 자객(은신·근접)·사냥꾼(원거리)·술사(사이오닉). 전투에서 죽여도 요새(Citadel)에서 부활 — 세 파트 비밀 작전으로 요새 공격 임무를 열고 성관(Sarcophagus) 파괴해야 영구 토벌. 각자 무작위 강점(최대 5)/약점(2 고정). 정보(Knowledge) 만달성 시 Avenger 직접 공격(방어 실패 시 패배) [S5][문서]</li></ul><h2 id="_9-이벤트-내러티브" tabindex="-1">9. 이벤트/내러티브 <a class="header-anchor" href="#_9-이벤트-내러티브" aria-label="Permalink to &quot;9. 이벤트/내러티브&quot;">​</a></h2><ul><li><strong>게릴라 옵스 구조</strong>: 매월 Dark Event 최대 3개 준비. 각 옵스 미션은 연계된 Dark Event 하나를 상쇄하나 <strong>한 달에 하나만 수행</strong> — 어떤 악사건을 용인할지 선택이 전략 핵심 [S3][S4][문서]</li><li><strong>Dark Event 사례</strong>: Avatar 진척 증가, XCOM 사냥(UFO), 보급 감소, 추가 적 배치, Faceless 잠입, 흑시장 폐업 등 30여 종. 은닉 이벤트는 20~30 Intel로 미리 확인 가능 [S3][문서]</li><li><strong>게릴라 옵스 미션 유형</strong>: 워크스테이션 해킹, 물품 회수, 통신 중계기 파괴, 장비 방어(유일 무타이머), 송신기 파괴, 야전 사령관 제거 등 [S4][문서]</li><li><strong>비밀 작전(WotC)</strong>: Resistance Ring에서 월 단위 수행. Chosen 사냥, 진척 방해(-2), 자원 확보. 위험(납치/매복/부상) 예방에 자원 추가 투입 가능 [S1][S6][문서]</li><li><strong>루머/스캔 이벤트</strong>: Geoscape 스캔으로 흑시장 개설, 세력 발견, 자원 확보 등 트리거 [S2][S6][문서]</li></ul><h2 id="_10-난이도-압박" tabindex="-1">10. 난이도/압박 <a class="header-anchor" href="#_10-난이도-압박" aria-label="Permalink to &quot;10. 난이도/압박&quot;">​</a></h2><ul><li><strong>전략 압박 — Avatar Project</strong>: 12칸 게이지. Dark Event·시설 건설·주기적 자연 증가로 상승. 완료 시 카운트다운(난이도별 15~27일) 후 패배. 감소: 외성인 시설 파괴(기여분 전부), 스토리 미션(1~3), 방해 작전(-2) [S1][문서]</li><li><strong>전술 압박</strong>: 턴 타이머, Dark Event 전투 악화, Chosen 등장 [S3][S4][S5][문서]</li><li><strong>인적 압박</strong>: 부상·사망·포로·피로가 병력 풀 압박. WotC 피로는 에이스 남용 차단 로테이션 강제 장치 [S5][S6][S12][문서]</li><li><strong>양층 위협 상호작용(설계 의도)</strong>: 전략 압박은 전술 미션을 강제하고, 전술 미션은 병력을 소모시켜 전략 여력을 깎는다. 시설 파괴·스토리 미션 외엔 진척을 되돌릴 수 없으므로 &#39;기다림&#39;은 항상 손해 — <strong>선공적 운영이 유일한 방어</strong> [S1][추론]</li><li><strong>난이도 설정</strong>: Rookie/Veteran/Commander/Legend. 필요 킬 수, 카운트다운 일수, 측면 치명타 보너스 등 수치 차이 [S1][S9][S12][문서]</li></ul>',26)])])}const u=o(l,[["render",s]]);export{d as __pageData,u as default};
